@Execution(ExecutionMode.SAME_THREAD)
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeParallelBackpressureCancellationTest {

	private static final String EX = "http://example.com/parallel-close/";
	// A single asynchronous worker cannot finish early because another worker claimed the productive ranges.
	private static final int WORKERS = 1;
	private static final int SUBJECTS = 1_024;

	@TempDir
	File dataDir;

	@Test
	@Timeout(30)
	void closingResultDrainsFullOutputQueueWithoutClosingConnection() throws Exception {
		Map<String, String> previousProperties = new HashMap<>();
		SailRepository repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		try {
			setProperty(previousProperties, "rdf4j.lmdb.nativeQueryEngine.enabled", "true");
			setProperty(previousProperties, "rdf4j.lmdb.parallel.enabled", "true");
			setProperty(previousProperties, "rdf4j.lmdb.parallel.minWorkEstimate", "0");
			setProperty(previousProperties, "rdf4j.lmdb.parallel.threads", Integer.toString(WORKERS));
			setProperty(previousProperties, "rdf4j.lmdb.parallel.maxTasks", Integer.toString(WORKERS + 1));
			setProperty(previousProperties, "rdf4j.lmdb.parallel.rangePartition.enabled", "true");
			setProperty(previousProperties, "rdf4j.lmdb.packedFtree.enabled", "false");
			setProperty(previousProperties, "rdf4j.lmdb.kernelInterpreter.enabled", "false");
			setProperty(previousProperties, "rdf4j.lmdb.janinoCodegen.enabled", "false");
			loadData(repository);
			Set<Thread> workers = ConcurrentHashMap.newKeySet();
			CountDownLatch workerScopesClosed = new CountDownLatch(WORKERS);
			long initialBatches = LmdbNativeParallelPipelines.OUTPUT_BATCHES.get();
			long initialRuns = LmdbNativeParallelPipelines.PARALLEL_ROW_RUNS.get();
			long initialPartitions = LmdbNativeParallelPipelines.RANGE_PARTITIONS_PLANNED.get();
			try (SailRepositoryConnection connection = repository.getConnection();
					var scope = QueryExecutionContext.activateReplaySafepoint(() -> {
					}, () -> () -> {
						workers.add(Thread.currentThread());
						return workerScopesClosed::countDown;
					})) {
				String sparql = "SELECT ?subject ?value ?value2 ?value3 WHERE { ?subject <" + EX
						+ "p1> ?middle . ?middle <" + EX + "p2> ?tail . ?tail <" + EX
						+ "p3> ?value . ?tail <" + EX + "p3> ?value2 . ?tail <" + EX + "p3> ?value3 . }";
				SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
				query.setForcedLmdbExecutionStrategy(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES);
				try (TupleQueryResult result = query.evaluate()) {
					assertThat(result.hasNext()).isTrue();
					result.next();
					assertThat(LmdbNativeParallelPipelines.PARALLEL_ROW_RUNS.get()).isEqualTo(initialRuns + 1L);
					awaitFullOutputQueue(workers, workerScopesClosed, initialBatches, initialPartitions);
					result.close();
					assertThat(workerScopesClosed.await(5, TimeUnit.SECONDS))
							.as("result close must drain every backpressured worker while its connection stays open"
									+ " (closed scopes: %s; completed output batches: %s)",
									WORKERS - workerScopesClosed.getCount(),
									LmdbNativeParallelPipelines.OUTPUT_BATCHES.get() - initialBatches)
							.isTrue();
					try (var reservation = LmdbNativeParallelPipelines.tryReserveTasks(true, WORKERS + 1)) {
						assertThat(reservation).as("result close releases every native worker reservation").isNotNull();
						assertThat(reservation.grantedWorkers()).isEqualTo(WORKERS + 1);
					}
					assertThat(connection.size()).isEqualTo(SUBJECTS * 5L);
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				previousProperties.forEach((name, value) -> {
					if (value == null) {
						System.clearProperty(name);
					} else {
						System.setProperty(name, value);
					}
				});
			}
		}
	}

	private static void setProperty(Map<String, String> previous, String name, String value) {
		previous.put(name, System.setProperty(name, value));
	}

	private static void loadData(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p1 = vf.createIRI(EX, "p1");
			IRI p2 = vf.createIRI(EX, "p2");
			IRI p3 = vf.createIRI(EX, "p3");
			connection.begin();
			for (int i = 0; i < SUBJECTS; i++) {
				IRI middle = vf.createIRI(EX, "m" + i);
				IRI tail = vf.createIRI(EX, "t" + i);
				connection.add(vf.createIRI(EX, "s" + i), p1, middle);
				connection.add(middle, p2, tail);
				for (int branch = 0; branch < 3; branch++) {
					connection.add(tail, p3, vf.createIRI(EX, "v" + i + "-" + branch));
				}
			}
			connection.commit();
		}
	}

	private static void awaitFullOutputQueue(Set<Thread> workers, CountDownLatch workerScopesClosed,
			long initialBatches, long initialPartitions) {
		ThreadMXBean threads = ManagementFactory.getThreadMXBean();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (System.nanoTime() < deadline) {
			// The queue holds two pages per worker, and the caller consumed exactly one page for its first row.
			// Requiring that vacated slot to have been refilled rules out a signalled but not yet resumed offer.
			if (workers.size() == WORKERS
					&& LmdbNativeParallelPipelines.OUTPUT_BATCHES.get() >= initialBatches + WORKERS * 2L + 1L
					&& workers.stream()
							.allMatch(worker -> inOutputWait(threads.getThreadInfo(worker.threadId(), 64)))) {
				return;
			}
			Thread.onSpinWait();
		}
		StringBuilder diagnostics = new StringBuilder(
				"every native worker must be blocked on a completely full output queue")
						.append(" (captured workers: ")
						.append(workers.size())
						.append("; closed scopes: ")
						.append(WORKERS - workerScopesClosed.getCount())
						.append("; completed output batches: ")
						.append(LmdbNativeParallelPipelines.OUTPUT_BATCHES.get() - initialBatches)
						.append("; planned partitions: ")
						.append(LmdbNativeParallelPipelines.RANGE_PARTITIONS_PLANNED.get() - initialPartitions)
						.append(')');
		for (Thread worker : workers) {
			ThreadInfo info = threads.getThreadInfo(worker.threadId(), 64);
			diagnostics.append('\n').append(worker.getName()).append(": ");
			if (info == null) {
				diagnostics.append("terminated");
			} else {
				diagnostics.append(info.getThreadState());
				for (StackTraceElement frame : info.getStackTrace()) {
					diagnostics.append("\n\tat ").append(frame);
				}
			}
		}
		throw new AssertionError(diagnostics.toString());
	}

	private static boolean inOutputWait(ThreadInfo thread) {
		if (thread == null || thread.getThreadState() != Thread.State.TIMED_WAITING) {
			return false;
		}
		StackTraceElement[] stack = thread.getStackTrace();
		return Arrays.stream(stack)
				.anyMatch(frame -> frame.getClassName()
						.equals(LmdbNativeParallelPipelines.ParallelRowCursor.class.getName())
						&& frame.getMethodName().equals("offerOutput"))
				&& Arrays.stream(stack)
						.anyMatch(frame -> frame.getClassName()
								.equals("java.util.concurrent.ArrayBlockingQueue")
								&& frame.getMethodName().equals("offer"));
	}
}
